const body = $json.body || $json;
const error = body.error || body;
const message = String(error.message || error.error_message || 'Unknown error');
const lower = message.toLowerCase();
let level = 'ERROR';
let retry_allowed = true;
let max_retries = 3;
let action = 'retry_with_backoff';
if (lower.includes('auth') || lower.includes('credential') || lower.includes('401') || lower.includes('403')) {
  level = 'ERROR'; retry_allowed = false; max_retries = 0; action = 'alert_consultant';
}
if (lower.includes('secret') || lower.includes('leak') || lower.includes('unauthorized publication') || lower.includes('client mix')) {
  level = 'CRITICAL'; retry_allowed = false; max_retries = 0; action = 'stop_and_alert_admin';
}
return [{ json: {
  level,
  retry_allowed,
  max_retries,
  action,
  client_id: error.client_id || 'unknown',
  workflow_name: error.workflow_name || 'unknown',
  agent: error.agent || 'Error Handler',
  error_message: message,
  metadata: error
}}];
